        else:
            groups[-1].append(r)

    for group in groups:
        if len(group) < 2:
            continue
        # Detect a repeated horizontal pattern in the motif and continue it
        # into the blank area to its right, highlighting newly continued cells.
        right = max(c for r in group for c, v in enumerate(grid[r]) if v != bg)
        if right == w - 1:
            continue
        width = right + 1
        period = None
        for p in range(1, width + 1):
            if all(grid[r][c] == grid[r][c % p]
                   for r in group for c in range(p, width)):
                period = p
                break
        if period is None:
            continue
